fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();

    // Only need to check parents, i in [0..n/2)
    // Because nodes beyond floor(n/2)-1 are leaves with no children.
    for i in 0..(n / 2) {
        let left = 2 * i + 1;
        let right = 2 * i + 2;

        // Check left child if it exists
        if left < n && a[i] > a[left] {
            return false;
        }

        // Check right child if it exists
        if right < n && a[i] > a[right] {
            return false;
        }
    }

    true
}